use std::hint::black_box;
use std::time::Instant;
#[path = "__NODES_REPOSITORY__/src/number_interpolation.rs"]
mod number_interpolation;
const N: usize = 16_384;
const SAMPLES: usize = 9;
#[derive(Clone, Copy)]
struct Case { a: f64, b: f64, t: f64, expected: u64 }
fn weighted(a:f64,b:f64,t:f64)->f64 {
    if t==0. { a } else if t==1. { b } else { (1.-t)*a+t*b }
}
const EXTREME: [[u64;4];16] = [
    [0x3ff0000000000000, 0xbca8000000000000, 0x7feffffffffffffe, 0xffefffffffffffff],
    [0x3ff0000000000000, 0xbca8000000000000, 0x7fefffffffffffff, 0xfff0000000000000],
    [0x3ff0000000000000, 0xbca8000000000000, 0xffeffffffffffffe, 0x7fefffffffffffff],
    [0x3ff0000000000000, 0xbca8000000000000, 0xffefffffffffffff, 0x7ff0000000000000],
    [0x7fefffffffffffff, 0xffefffffffffffff, 0x3fdfffffffffffff, 0x7c9fffffffffffff],
    [0x7fefffffffffffff, 0x7fefffffffffffff, 0x7fefffffffffffff, 0x7fefffffffffffff],
    [0x7fefffffffffffff, 0xffefffffffffffff, 0x3fe0000000000000, 0x0000000000000000],
    [0x0000000000000000, 0x8000000000000001, 0x3fe0000000000000, 0x8000000000000000],
    [0x0000000000000000, 0x0000000000000003, 0x3fe0000000000000, 0x0000000000000002],
    [0x0000000000000000, 0x8000000000000001, 0x0000000000000001, 0x8000000000000000],
    [0xbff0000000000000, 0x3ca0000000000000, 0x3fefffffffffffff, 0xb950000000000000],
    [0x4350000000000000, 0x3ff0000000000000, 0x3ff0000000000001, 0xc008000000000000],
    [0x3ff0000000000000, 0x3ff0000000000001, 0x7fefffffffffffff, 0x7cafffffffffffff],
    [0x0010000000000000, 0x0010000000000001, 0x7fefffffffffffff, 0x3ccfffffffffffff],
    [0x0000000000000001, 0x8000000000000001, 0x7fefffffffffffff, 0xbcdfffffffffffff],
    [0x7fefffffffffffff, 0xffefffffffffffff, 0x4000000000000000, 0xfff0000000000000]
];
fn fixtures(name: &str) -> Vec<Case> {
    (0..N).map(|i| match name {
        "ordinary_0_to_1" => {
            let ai=(i%97) as i64-48;
            let bi=(i%13) as i64-6;
            let ti=(i%257) as i64;
            Case { a:ai as f64,b:ai as f64+bi as f64/4.,t:ti as f64/256.,expected:((1024*ai+bi*ti) as f64/1024.).to_bits() }
        }
        "finite_extrapolation" => {
            let ai=(i%97) as i64-48;
            let bi=(i%89) as i64-44;
            let tn=if i%2==0 { -(16+(i%29) as i64) } else { 16+(i%29) as i64 };
            Case { a:ai as f64/1024.,b:bi as f64/512.,t:tn as f64/8.,expected:((8*ai+tn*(2*bi-ai)) as f64/8192.).to_bits() }
        }
        "extreme_finite_inputs" => {
            let [a,b,t,expected]=EXTREME[i%EXTREME.len()];
            Case { a:f64::from_bits(a),b:f64::from_bits(b),t:f64::from_bits(t),expected }
        }
        _=>unreachable!(),
    }).collect()
}
fn measure(name:&str,method:&str,function:fn(f64,f64,f64)->f64,cases:&[Case]) {
    let repetitions=N/cases.len();
    let function=black_box(function);
    let mut output=vec![0.;cases.len()];
    let mut run=|| {
        for _ in 0..repetitions {
            for (out,c) in output.iter_mut().zip(cases) {
                *out=black_box(function(black_box(c.a),black_box(c.b),black_box(c.t)));
            }
        }
    };
    run();
    let mut durations=Vec::with_capacity(SAMPLES);
    let mut failures=Vec::with_capacity(SAMPLES);
    let mut first_error=None;
    for _ in 0..SAMPLES {
        let start=Instant::now();
        for _ in 0..repetitions {
            for (out,c) in output.iter_mut().zip(cases) {
                *out=black_box(function(black_box(c.a),black_box(c.b),black_box(c.t)));
            }
        }
        durations.push(start.elapsed().as_nanos());
        let mut mismatches=0;
        for (index,(out,c)) in output.iter().zip(cases).enumerate() {
            if out.to_bits()!=c.expected {
                mismatches+=1;
                first_error.get_or_insert((index,out.to_bits(),c.expected));
            }
        }
        failures.push(mismatches);
    }
    let expected_overflow=cases.iter().filter(|c|f64::from_bits(c.expected).is_infinite()).count();
    let detail=first_error.map_or("null".to_owned(),|(i,a,e)|format!("{{\"index\":{i},\"actual_bits\":\"{a:016x}\",\"expected_bits\":\"{e:016x}\"}}"));
    println!("{{\"workload\":\"{name}\",\"method\":\"{method}\",\"logical_batch_size\":{},\"repetitions_per_sample\":{repetitions},\"calls_per_sample\":{N},\"warmup_calls\":{N},\"sample_count\":{SAMPLES},\"duration_ns_per_sample\":{durations:?},\"mismatched_results_per_sample\":{failures:?},\"first_mismatch\":{detail},\"expected_infinite_outputs_per_logical_batch\":{expected_overflow}}}",cases.len());
}
fn main() {
    for name in ["ordinary_0_to_1","finite_extrapolation","extreme_finite_inputs"] {
        let cases=fixtures(name);
        let single=[cases[if name=="extreme_finite_inputs" {0} else if name=="ordinary_0_to_1" {124} else {123}]];
        for input in [&single[..],&cases[..]] {
            measure(name,"weighted_a1ffa400",weighted,input);
            measure(name,"exact_fixed_point",number_interpolation::lerp,input);
        }
    }
}
